// SIMPLE WORKING PRICE DROP WIDGET
(function() {
    console.log(" Widget script loading...");
    
    class PriceDropWidget {
        constructor(options = {}) {
            this.options = options;
            this.container = document.querySelector(options.container);
            this.init();
        }
        
        init() {
            if (!this.container) {
                console.error("Container not found:", this.options.container);
                return;
            }
            
            this.container.innerHTML = `
                <div style="
                    border: 1px solid #2563eb;
                    border-radius: 8px;
                    padding: 20px;
                    max-width: 400px;
                    background: white;
                ">
                    <h3 style="margin-top: 0; color: #2563eb;">Price Drop Alert</h3>
                    <p>Get notified when price drops</p>
                    
                    <div style="display: flex; gap: 10px; margin: 15px 0;">
                        <input type="email" 
                               placeholder="your@email.com" 
                               style="flex: 1; padding: 10px; border: 1px solid #ccc; border-radius: 4px;"
                               id="email-input">
                        <button style="
                            background: #2563eb;
                            color: white;
                            border: none;
                            padding: 10px 20px;
                            border-radius: 4px;
                            cursor: pointer;
                        " onclick="this.handleSubmit()">Notify Me</button>
                    </div>
                    
                    <div id="message" style="
                        padding: 10px;
                        border-radius: 4px;
                        margin-top: 10px;
                        display: none;
                    "></div>
                    
                    <div style="
                        background: #f3f4f6;
                        padding: 10px;
                        border-radius: 4px;
                        font-size: 14px;
                        margin-top: 15px;
                    ">
                        <p><strong>Product:</strong> ${this.options.productName || "Product"}</p>
                        <p><strong>Price:</strong> ${this.options.productPrice || "$0.00"}</p>
                    </div>
                </div>
            `;
            
            // Store references
            this.emailInput = this.container.querySelector("#email-input");
            this.messageDiv = this.container.querySelector("#message");
            this.button = this.container.querySelector("button");
            
            // Bind event
            this.button.handleSubmit = () => this.handleSubmit();
        }
        
        async handleSubmit() {
            const email = this.emailInput.value;
            
            if (!email.includes("@")) {
                this.showMessage("Please enter valid email", "error");
                return;
            }
            
            this.showMessage("Sending...", "info");
            this.button.disabled = true;
            
            try {
                const response = await fetch("/subscribe-price-drop", {
                    method: "POST",
                    headers: {"Content-Type": "application/json"},
                    body: JSON.stringify({
                        email: email,
                        product: {
                            name: this.options.productName || "Product",
                            price: this.options.productPrice || "$0",
                            url: this.options.productUrl || window.location.href
                        }
                    })
                });
                
                const data = await response.json();
                
                if (data.ok) {
                    this.showMessage(" You'll be notified!", "success");
                } else {
                    this.showMessage(` Error: ${data.error}`, "error");
                }
            } catch (error) {
                this.showMessage(" Network error", "error");
            }
            
            this.button.disabled = false;
        }
        
        showMessage(text, type) {
            this.messageDiv.textContent = text;
            this.messageDiv.style.display = "block";
            this.messageDiv.style.background = 
                type === "error" ? "#fee2e2" : 
                type === "success" ? "#dcfce7" : "#e0f2fe";
            this.messageDiv.style.color = 
                type === "error" ? "#991b1b" : 
                type === "success" ? "#166534" : "#0c4a6e";
                
            if (type !== "info") {
                setTimeout(() => {
                    this.messageDiv.style.display = "none";
                }, 5000);
            }
        }
    }
    
    // Register globally
    window.PriceDropWidget = PriceDropWidget;
    console.log(" PriceDropWidget class registered successfully!");
})();
